"""A headless terminal implementation of the BaseTerminal interface.

HeadlessTerminal spawns an interactive bash shell attached to a pseudo-terminal
(PTY). Keystrokes are written to the master side of the PTY exactly as a user
would type them, and the shell's output is fed through a pyte terminal emulator
so that the current screen contents can be inspected.
"""

import os
import pty
import select
import signal
import time

import pyte

from base_terminal import BaseTerminal


class HeadlessTerminal(BaseTerminal):
    def __init__(self, rows: int = 24, cols: int = 80, env: dict | None = None):
        self.rows = rows
        self.cols = cols

        # pyte screen + stream turn the raw byte stream from the PTY into a
        # rendered, inspectable screen (handles cursor moves, colors, etc.).
        self._screen = pyte.Screen(cols, rows)
        self._stream = pyte.ByteStream(self._screen)

        # Fork a child attached to a new PTY. In the child, exec an interactive
        # bash shell so that startup files (e.g. ~/.bashrc) are sourced.
        child_env = os.environ.copy()
        if env:
            child_env.update(env)
        # A real terminal type so interactive programs behave.
        child_env.setdefault("TERM", "linux")
        child_env["LINES"] = str(rows)
        child_env["COLUMNS"] = str(cols)

        pid, master_fd = pty.fork()
        if pid == 0:
            # Child process: become an interactive login-capable bash shell.
            try:
                os.execvpe("bash", ["bash", "-i"], child_env)
            except Exception:
                os._exit(127)

        self.pid = pid
        self.master_fd = master_fd

        # Inform the kernel of the window size so full-screen apps render right.
        try:
            import fcntl
            import struct
            import termios

            winsize = struct.pack("HHHH", rows, cols, 0, 0)
            fcntl.ioctl(self.master_fd, termios.TIOCSWINSZ, winsize)
        except Exception:
            pass

        # Drain the shell's startup banner / prompt so the screen reflects a
        # ready-to-use terminal.
        self._drain(0.5)

    def send_keystrokes(self, keystrokes: str, wait_sec: float = 0.0) -> None:
        """
        Sends keystrokes to the terminal.

        Args:
            keystrokes: The keystrokes to send to the terminal.
            wait_sec: The number of seconds to wait for the command to complete.
        """
        data = keystrokes.encode("utf-8", errors="surrogateescape")
        while data:
            written = os.write(self.master_fd, data)
            data = data[written:]
        # Read output for at least wait_sec seconds so the screen reflects the
        # result of the command that was just sent.
        self._drain(wait_sec)

    def _drain(self, wait_sec: float) -> None:
        """Read available PTY output for up to wait_sec seconds, feeding pyte."""
        deadline = time.time() + wait_sec
        while True:
            remaining = deadline - time.time()
            timeout = remaining if remaining > 0 else 0.0
            try:
                readable, _, _ = select.select([self.master_fd], [], [], timeout)
            except (OSError, ValueError):
                break
            if readable:
                try:
                    chunk = os.read(self.master_fd, 65536)
                except OSError:
                    break
                if not chunk:
                    break
                self._stream.feed(chunk)
            if time.time() >= deadline:
                break

    def read_screen(self) -> str:
        """Return the current rendered screen as text (one line per row)."""
        return "\n".join(self._screen.display)

    def read_screen_stripped(self) -> str:
        """Return the screen with trailing whitespace stripped from each line
        and trailing blank lines removed."""
        lines = [line.rstrip() for line in self._screen.display]
        while lines and lines[-1] == "":
            lines.pop()
        return "\n".join(lines)

    def close(self) -> None:
        """Terminate the shell and clean up resources."""
        try:
            os.close(self.master_fd)
        except OSError:
            pass
        if self.pid:
            try:
                os.kill(self.pid, signal.SIGKILL)
            except OSError:
                pass
            try:
                os.waitpid(self.pid, 0)
            except OSError:
                pass
            self.pid = None

    def __del__(self):
        try:
            self.close()
        except Exception:
            pass

