def close(self) -> None:
    """Terminate the shell and clean up resources."""
    fd = getattr(self, "master_fd", -1)
    if fd is not None and fd >= 0:
        try:
            os.close(fd)
        except OSError:
            pass
        # Prevent a later __del__ from closing a recycled fd number.
        self.master_fd = -1
    if getattr(self, "pid", None):
        try:
            os.kill(self.pid, signal.SIGKILL)
        except OSError:
            pass
        try:
            os.waitpid(self.pid, 0)
        except OSError:
            pass
        self.pid = None
